#include <iostream>
#include <limits>
#include <sstream>

void discardLine(std::istream& input)
{
    input.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
}

int main()
{
    std::istringstream input{"old suffix\n42\n"};
    discardLine(input);
    int next{};
    input >> next;
    std::cout << next << '\n';
    return 0;
}

