#define main learner_main
#include "main.cpp"
#undef main
#include <string>

int main()
{
    int failures{};
    for (const std::string& suffix : {std::string{}, std::string{"junk 17"}, std::string(12000, 'x')})
    {
        std::istringstream input{suffix + "\n42\n73\n"};
        discardLine(input);
        if (input.peek() != '4')
        {
            std::cerr << "Must consume newline but preserve following line; suffix length " << suffix.size() << '\n';
            ++failures;
        }
        int first{}, second{};
        if (!(input >> first >> second) || first != 42 || second != 73)
        {
            std::cerr << "Next two tokens were not preserved\n";
            ++failures;
        }
    }
    std::istringstream finalLine{"tail without newline"};
    discardLine(finalLine);
    if (!finalLine.eof() || finalLine.rdbuf()->sgetc() != std::char_traits<char>::eof())
    {
        std::cerr << "Unterminated suffix must be consumed to EOF\n";
        ++failures;
    }
    std::istringstream empty{};
    discardLine(empty);
    if (!empty.eof())
    {
        std::cerr << "Empty source must reach EOF\n";
        ++failures;
    }
    return failures == 0 ? 0 : 1;
}

