#include <iostream>
#include <limits>
#include <sstream>

bool readNumber(std::istream& input, int& result)
{
    while (true)
    {
        int candidate{};
        if (input >> candidate)
        {
            input.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            result = candidate;
            return true;
        }
        if (input.eof()) return false;
        input.clear();
        input.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }
}

int main()
{
    std::istringstream input{"bad\n-6 extra\n"};
    int result{};
    if (readNumber(input, result)) std::cout << result << '\n';
    return 0;
}

