#define main learner_main
#include "main.cpp"
#undef main
#include <string>

int main()
{
    int failures{};
    auto check = [&](const std::string& text, bool expectedSuccess, int expectedValue, const char* label)
    {
        std::istringstream input{text};
        int result{314};
        const bool success{readNumber(input, result)};
        if (success != expectedSuccess || result != expectedValue)
        {
            std::cerr << label << ": success=" << success << ", result=" << result << '\n';
            ++failures;
        }
    };
    check("bad\n-6 extra\n", true, -6, "recover from text, keep negative");
    check("0\n", true, 0, "zero is valid");
    check("20", true, 20, "successful final token");
    check(" \t\n+8tail\n", true, 8, "skip whitespace and accept prefix");
    check(std::to_string(std::numeric_limits<int>::max()) + "0\n11\n", true, 11, "positive overflow");
    check(std::to_string(std::numeric_limits<int>::min()) + "0\n12\n", true, 12, "negative overflow");
    check(std::to_string(std::numeric_limits<int>::max()), true, std::numeric_limits<int>::max(), "maximum valid int at EOF");
    check(std::to_string(std::numeric_limits<int>::min()), true, std::numeric_limits<int>::min(), "minimum valid int at EOF");
    check("", false, 314, "empty input preserves output");
    check(" \t\n", false, 314, "whitespace only");
    check("bad\nmore bad", false, 314, "EOF after invalid attempts");
    check(std::to_string(std::numeric_limits<int>::max()) + "0", false, 314, "overflow ending at EOF");
    std::istringstream sequence{"bad 99\n5 " + std::string(12000, 'x') + " 88\n9\n"};
    int first{}, second{};
    if (!readNumber(sequence, first) || first != 5 || !readNumber(sequence, second) || second != 9)
    {
        std::cerr << "Discard complete bad and successful suffixes, preserving next line\n";
        ++failures;
    }
    int untouched{271};
    if (readNumber(sequence, untouched) || untouched != 271)
    {
        std::cerr << "Repeated call after exhaustion must return false without overwriting output\n";
        ++failures;
    }
    return failures == 0 ? 0 : 1;
}
